<script setup lang="ts">
import MinutesSettings from './MinutesSettings.vue';import {captureEvidenceAnchors,reanchorEvidence} from './minutes-anchors';
import PublicationPanel from './PublicationPanel.vue';import {useEditorIntent} from '../../shared/composables/useEditorIntent';
import {computed,shallowRef,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {useMinutesEditor} from './useMinutesEditor';import {useMinutesActions} from './useMinutesActions';import MinutesTextEditor from './MinutesTextEditor.vue';import MinutesHistory from './MinutesHistory.vue';import type {components} from '../../shared/api/generated';
import type {MinutesCurrent,MinutesOperation} from '../../shared/api/minutes-saved';import type {Candidate,Candidates,Source} from '../../shared/api/minutes-inspection';import type {MinutesTarget} from './minutes-editor-journal';import {ApiError} from '../../shared/api/client';import {scalarOffset} from '../../shared/scalar-anchors';
const props=defineProps<{meetingId:string;owner:boolean}>();const emit=defineEmits<{changed:[]}>();const app=useApplication(),actor=()=>app.session.current.value?.actor.enterpriseId??null;
const accessDenied=ref(false);const allowed=()=>props.owner&&app.minutesScopeReady.value&&!accessDenied.value;const authorize=async(id:string,signal:AbortSignal)=>{const v=await app.workspace.navigation(id,signal);return v.relation==='OWNER'&&['CHECK_PRODUCER','PUBLISHED_READ_ONLY'].includes(v.navigationState);};
const editor=useMinutesEditor({...app.minutesSaved,authorize},actor,()=>props.meetingId,allowed,app.journals);const publicCurrent=shallowRef<MinutesCurrent|null>(null),error=ref(''),busy=ref(false),source=shallowRef<Source|null>(null),candidates=shallowRef<Candidates|null>(null),candidate=shallowRef<Candidate|null>(null),candidateState=ref<'PENDING'|'STALE'|'ADOPTED'|'REJECTED'>('PENDING');
const reviewHistory=shallowRef<components['schemas']['SavedReviewHistory']|null>(null),candidatePage=ref(0);
const selected=shallowRef<{kind:'BODY'|'ELEMENT';id:string}|null>(null),reviewOutcome=ref<'SUPPORTED'|'PARTIAL'|'UNSUPPORTED'>('SUPPORTED'),reviewSelection=ref<{startToken:string;endToken:string}|null>(null);const pages=ref<Record<string,number>>({});
let epoch=0,controller:AbortController|null=null;const value=computed(()=>props.owner?editor.current.value:publicCurrent.value);const locked=computed(()=>!allowed()||!!value.value?.observation.readOnlyReason||!value.value||editor.draft.value?.dirty.value||['PREPARED','SENDING','UNCERTAIN'].includes(editor.command.state.value));
const actionSession={},actionIntent=useEditorIntent(()=>allowed()&&actor()?{actor:actor()!,meetingId:props.meetingId,session:actionSession}:null,()=>!!locked.value,c=>app.minutesSaved.intent(c));
const actions=useMinutesActions({authorize:async(id,signal)=>{const v=await app.workspace.navigation(id,signal);return v.relation==='OWNER'&&v.navigationState==='CHECK_PRODUCER';},send:app.minutesSaved.send},actor,()=>props.meetingId,allowed,async()=>{await editor.reload();emit('changed');},app.journals);
const selectedContent=computed(()=>{const t=selected.value,v=value.value;if(!t||!v)return null;if(t.kind==='BODY')return v.body?.id===t.id?v.body:null;return Object.values(v.elements).flat().find(x=>x.id===t.id)??null;});
function denied(cause:unknown){accessDenied.value=true;epoch++;controller?.abort();editor.deny(cause);actions.deny(cause);actionIntent.invalidate();reviewHistory.value=null;publicCurrent.value=null;source.value=null;candidates.value=null;candidate.value=null;selected.value=null;error.value=cause instanceof Error?cause.message:'访问权限已变化。';}
async function read<T>(fn:(signal:AbortSignal)=>Promise<T>,accept:(v:T)=>void){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;busy.value=true;error.value='';try{const v=await fn(request.signal);if(turn===epoch)accept(v);}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status))denied(cause);else error.value=cause instanceof Error?cause.message:'读取失败。';}}finally{if(turn===epoch)busy.value=false;}}
async function reload(){actionIntent.invalidate();reviewHistory.value=null;accessDenied.value=false;source.value=null;selected.value=null;candidate.value=null;candidates.value=null;if(props.owner){await actions.reload();await editor.reload();}else await read(s=>app.minutesSaved.current(props.meetingId,s),v=>publicCurrent.value=v);}
function inspect(t:{kind:'BODY'|'ELEMENT';id:string}){reviewHistory.value=null;actionIntent.invalidate();selected.value=t;source.value=null;reviewSelection.value=null;}

async function edit(t:MinutesTarget){try{await editor.select(t);error.value='';}catch(e){error.value=e instanceof Error?e.message:'编辑不可用。';}}
async function command(operation:MinutesOperation,fields:Record<string,unknown>,id?:string){try{if(locked.value)throw new Error('请先保存草稿并重新读取当前纪要。');const revision=value.value!.observation.revisionToken,turn=epoch;actionIntent.invalidate();await actionIntent.request(revision);if(turn!==epoch||locked.value)return;await actions.run(operation,{expectedRevisionToken:revision,...fields},id);source.value=null;selected.value=null;candidate.value=null;candidates.value=null;}catch(e){error.value=e instanceof Error?e.message:'操作不可用。';}}
function loadCandidates(next:string|null=null){candidate.value=null;void read(s=>app.minutesInspection.candidates(props.meetingId,candidateState.value,next,s),v=>candidates.value=v);}
function review(span=false){if(!selected.value||!selectedContent.value||span&&!reviewSelection.value)return;void command('MINUTES_REVIEW',{target:{kind:selected.value.kind,id:selected.value.id},reviewKind:'SOURCE_SUPPORT',scope:span?'SPAN':'WHOLE',outcome:reviewOutcome.value,...(span?reviewSelection.value:{})});}
function range(event:Event){const e=event.target as HTMLTextAreaElement;reviewSelection.value=e.selectionEnd>e.selectionStart?{startToken:scalarOffset(e.value,e.selectionStart),endToken:scalarOffset(e.value,e.selectionEnd)}:null;}
async function convertQuestion(){const t=selected.value,v=value.value,c=selectedContent.value;if(!t||t.kind!=='ELEMENT'||!v?.setId||!c)return;try{const anchor=await captureEvidenceAnchors(c.body,v.evidence.filter(e=>e.element_id===t.id));await command('MINUTES_OPEN_QUESTION',{sourceSetId:v.setId,body:c.body,evidenceAnchors:reanchorEvidence(c.body,anchor)},t.id);}catch(e){error.value=e instanceof Error?e.message:'来源位置暂不可确认。';}}
function loadReviews(next:string|null=null){const t=selected.value;if(t)void read(s=>app.minutesInspection.reviews(props.meetingId,t,next,s),v=>reviewHistory.value=v);}
const stopErrors=watch(()=>[editor.error.value,actions.error.value],values=>{const failure=values.find(x=>x instanceof ApiError&&[401,403].includes(x.status));if(failure&&!accessDenied.value)denied(failure);},{flush:'sync'});
const stop=watch(()=>[actor(),props.meetingId,props.owner,app.minutesScopeReady.value],()=>{epoch++;controller?.abort();publicCurrent.value=null;source.value=null;candidates.value=null;candidate.value=null;selected.value=null;error.value='';pages.value={};if(actor())void reload();},{immediate:true,flush:'sync'});
onUnmounted(()=>{stopErrors();stop();epoch++;controller?.abort();editor.dispose();actions.dispose();actionIntent.invalidate();});
</script>
<template><section class="card minutes"><header><h2>纪要与审阅</h2><button class="btn" :disabled="busy||editor.loading.value" @click="reload">刷新纪要</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="owner&&!app.minutesScopeReady.value" role="alert">恢复记录暂不可用，请使用页面上方的恢复检查。</p>
 <template v-if="value"><p v-if="value.observation.readOnlyReason">当前纪要只读：{{value.observation.readOnlyReason}}</p><article v-if="value.body"><h3>{{value.body.title}}</h3><pre>{{value.body.body}}</pre><button class="btn" @click="inspect({kind:'BODY',id:value.body.id})">查看正文来源与审阅</button><button v-if="owner" class="btn" :disabled="locked" @click="edit({kind:'BODY',id:value.body.id})">编辑正文</button></article><p v-else>尚无已保存正文。生成完成后可在候选中检查结果。</p>
 <div v-for="(items,category) in value.elements" :key="category"><template v-if="items.length"><h3>{{category}}</h3><article v-for="item in items.slice((pages[category]??0)*20,((pages[category]??0)+1)*20)" :key="item.id"><p class="text">{{item.body}}</p><p v-if="item.action">负责人：{{item.action.owner_display??'未指定'}} · 日期：{{item.action.due_on??'未指定'}}</p><button class="btn" @click="inspect({kind:'ELEMENT',id:item.id})">来源与审阅</button><button v-if="owner" class="btn" :disabled="locked" @click="edit({kind:'ELEMENT',id:item.id})">编辑要素</button></article><button v-if="(pages[category]??0)>0" class="btn" @click="pages[category]=(pages[category]??0)-1">上一页</button><button v-if="((pages[category]??0)+1)*20<items.length" class="btn" @click="pages[category]=(pages[category]??0)+1">下一页</button></template></div>
 <section v-if="selected&&selectedContent" class="inspection"><h3>所选内容的来源</h3><textarea readonly rows="6" :value="selectedContent.body" @select="range"/><ul><li v-for="e in value.evidence.filter(e=>selected?.kind==='BODY'?e.minutes_revision_id===selected.id:e.element_id===selected?.id)" :key="e.id">{{e.support_state}} <button class="btn" @click="read(s=>app.minutesInspection.source(meetingId,e.locator_id,selected!,s),v=>source=v)">查看原始段落</button></li></ul><article v-if="source"><pre>{{source.text}}</pre><p>来源版本 {{source.sourceVersion}} · {{source.marks.join('、')}}</p><a :href="source.originalBytes.route" target="_blank" rel="noopener">读取原始文件</a></article>
  <div v-if="owner"><label>来源支持结论<select v-model="reviewOutcome"><option value="SUPPORTED">有充分支持</option><option value="PARTIAL">部分支持</option><option value="UNSUPPORTED">无支持</option></select></label><button class="btn" :disabled="locked" @click="review(false)">提交全文审阅</button><button class="btn" :disabled="locked||!reviewSelection" @click="review(true)">审阅所选文字</button><p>局部审阅不会替代全文审阅。</p><button class="btn" @click="loadReviews()">读取审阅记录</button><ul v-if="reviewHistory"><li v-for="r in reviewHistory.items" :key="r.id">{{r.review_kind}} · {{r.outcome}} · {{r.reviewed_by}} · {{r.reviewed_at}}</li></ul><button v-if="reviewHistory?.hasMore" class="btn" @click="loadReviews(reviewHistory.nextBeforeReviewNoToken)">下一页审阅</button><button v-if="selected.kind==='ELEMENT'" class="btn" :disabled="locked" @click="convertQuestion">转换为待确认问题</button>
   <template v-if="'action' in selectedContent&&selectedContent.action"><h4>行动项已接受字段</h4><p>企业负责人身份保留已保存值；当前页面不提供新的企业身份选择。</p><button class="btn" :disabled="locked" @click="edit({kind:'ACTION',id:selected!.id})">编辑负责人和截止日期</button><button class="btn" :disabled="locked" @click="command('MINUTES_REVIEW',{target:{kind:'ELEMENT',id:selected!.id},reviewKind:'ACTION_FIELDS',scope:null,outcome:'CONFIRMED'})">确认已保存的负责人和日期</button></template>
  </div>
 </section>
 </template>
 <template v-if="owner&&app.minutesScopeReady.value&&!accessDenied"><MinutesTextEditor :editor="editor" @saved="emit('changed')"/><section><h3>生成候选</h3><select v-model="candidateState" @change="candidates=null;candidate=null"><option value="PENDING">待决定</option><option value="STALE">已过期</option><option value="ADOPTED">已采用</option><option value="REJECTED">已拒绝</option></select><button class="btn" :disabled="busy" @click="loadCandidates()">读取候选</button><ul v-if="candidates"><li v-for="item in candidates.items" :key="item.candidateId">{{item.state}} · {{item.createdAt}} <button class="btn" @click="read(s=>app.minutesInspection.candidate(meetingId,item.candidateId,s),v=>candidate=v)">检查候选</button></li></ul><button v-if="candidates?.nextCursor" class="btn" @click="loadCandidates(candidates.nextCursor)">下一页</button><article v-if="candidate"><p>{{candidate.candidate.state}} · {{candidate.eligibility.reasons.join('、')}}</p><div v-for="body in candidate.graph.minutes_revision" :key="body.id"><h4>{{body.title}}</h4><pre>{{body.body}}</pre></div><div v-for="element in candidate.graph.minutes_element.slice(candidatePage*20,(candidatePage+1)*20)" :key="element.id"><h4>{{element.category}} · {{element.support_state}}</h4><p class="text">{{element.body}}</p><p v-for="suggestion in candidate.graph.action_suggestion.filter(x=>x.element_id===element.id)" :key="suggestion.element_id">建议负责人：{{suggestion.owner_mention??'未提供'}} · 建议日期：{{suggestion.due_on??'未提供'}}（尚未接受）</p></div><button v-if="candidatePage>0" class="btn" @click="candidatePage--">上一页候选要素</button><button v-if="(candidatePage+1)*20<candidate.graph.minutes_element.length" class="btn" @click="candidatePage++">下一页候选要素</button><p>采用后将建立新的已保存正文和要素集合；人工标题由服务器按当前规则保护。</p><button class="btn" :disabled="locked||!candidate.eligibility.canAdopt" @click="command('MINUTES_ADOPT',{inputId:candidate!.candidate.inputId,inputFingerprint:candidate!.candidate.inputFingerprint},candidate!.candidate.candidateId)">采用此候选</button><button class="btn" :disabled="locked||candidate.candidate.state!=='PENDING'" @click="command('MINUTES_REJECT',{},candidate!.candidate.candidateId)">拒绝此候选</button><button class="btn" :disabled="locked||!['PENDING','STALE'].includes(candidate.candidate.state)" @click="command('MINUTES_DISPOSE',{},candidate!.candidate.candidateId)">处置此候选</button></article></section>
 <MinutesSettings v-if="value" :meeting-id="meetingId" :current="value" :locked="!!locked" :editable="actionIntent.canEdit.value" @begin="actionIntent.request(value.observation.revisionToken).catch(e=>error=e.message)" @save="(op,fields)=>command(op,fields)" @denied="denied"/>
 <MinutesHistory :meeting-id="meetingId" :enabled="true" :locked="!!locked" @denied="denied" @restore="(kind,id)=>command(kind==='BODY'?'MINUTES_BODY_RESTORE':'MINUTES_SET_RESTORE',kind==='BODY'?{sourceRevisionId:id}:{sourceSetId:id})"/>
 <p v-if="actions.error.value" role="alert">{{actions.error.value instanceof Error?actions.error.value.message:'原操作结果待确认。'}}</p><button v-if="['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(actions.command.state.value)&&actions.command.snapshot.value" class="btn" :disabled="actions.busy.value" @click="actions.retry">查回原决定结果</button><button v-if="['CONFLICT','REJECTED'].includes(actions.command.state.value)" class="btn" @click="actions.reset();reload()">重新读取后再决定</button>
 </template><PublicationPanel v-if="!accessDenied" :meeting-id="meetingId" :owner="owner" :locked="!!locked||actions.busy.value||['PREPARED','SENDING','UNCERTAIN'].includes(actions.command.state.value)" @changed="reload" @denied="denied"/></section></template>
<style scoped>.minutes{padding:24px;margin:20px 0}.minutes header{display:flex;justify-content:space-between;align-items:center}.minutes h2{font-size:20px}.minutes h3{font-size:17px;margin-top:24px}.minutes article,.inspection{padding:14px;border:1px solid var(--border);border-radius:8px;margin:12px 0}.minutes pre,.text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.minutes pre{max-height:420px;overflow:auto}.minutes button{margin:6px}.minutes textarea{width:100%;box-sizing:border-box}.minutes label{display:block;margin:8px 0}.minutes input,.minutes select{margin:6px;padding:7px}button:disabled{opacity:.5}</style>
